#define time iTime
#define resolution iResolution.xy
float happy_star(vec2 uv, float anim)
{
    uv = abs(uv);
    vec2 pos = min(uv.xy/uv.yx, anim);
    float p = (2.0 - pos.x - pos.y);
    return (2.0+p*(p*p-1.5)) / (uv.x+uv.y);      
}
#define NUM_LAYERS 8.
#define TAU 6.28318
#define PI 3.141592
#define Velocity .025 //modified value to increse or decrease speed, negative value travel backwards
#define StarGlow 0.025
#define StarSize 02.
#define CanvasView 20.


float Star(vec2 uv, float flare){
    float d = length(uv);
  	float m = sin(StarGlow*1.2)/d;  
    float rays = max(0., .5-abs(uv.x*uv.y*1000.)); 
    m += (rays*flare)*2.;
    m *= smoothstep(1., .1, d);
    return m;
}

float Hash21(vec2 p){
    p = fract(p*vec2(123.34, 456.21));
    p += dot(p, p+45.32);
    return fract(p.x*p.y);
}


vec3 StarLayer(vec2 uv){
    vec3 col = vec3(0);
    vec2 gv = fract(uv);
    vec2 id = floor(uv);
    for(int y=-1;y<=1;y++){
        for(int x=-1; x<=1; x++){
            vec2 offs = vec2(x,y);
            float n = Hash21(id+offs);
            float size = fract(n);
            float star = Star(gv-offs-vec2(n, fract(n*34.))+.5, smoothstep(.1,.9,size)*.46);
            vec3 color = sin(vec3(3.2,.3,.9)*fract(n*2345.2)*TAU)*.25+.75;
            color = color*vec3(0.9,0.59,.9+size);
            star *= sin(iTime*1.0+n*TAU)*.5+.5;
            col += star*size*color;
        }
    }
    return col;
}

float snow(vec2 uv,float scale)
{
	float w=smoothstep(1.,0.,-uv.y*(scale/10.));if(w<.0)return 0.;
  float t3 = iTime * .1 + ((.25 + .05 * sin(iTime * .1))/(length(uv.xy) + .27)) * 12.2;
	float si = sin(t3);
	float co = cos(t3);
	mat2 ma = mat2(co, si, -si, co);

        uv*=ma;
	uv*=scale;vec2 s=floor(uv),f=fract(uv),p;float k=40.,d;
     f*=ma;

	p=.5+.35*sin(11.*fract(sin((s+p+scale)*mat2(7,3,6,5))*5.))-f;d=length(p);k=min(d,k);
	k=smoothstep(0.,k,sin(f.x+f.y)*0.003);
    	return k*w;
}
#define SPEED 1.2
#define INTENSITY 1.0

#define MAX_ITER 5

uniform float spectrum;




void mainImage( out vec4 fragColor, in vec2 fragCoord ){
	vec2 uv=(gl_FragCoord.xy*2.-resolution.xy)/min(resolution.x,resolution.y);

   uv/=1.-uv.y*0.5;
   float t3 = iTime * .1 + ((.25 + .05 * sin(iTime * .1))/(length(uv.xy) + .07)) * 2.2;
	float si = sin(t3);
	float co = cos(t3);
	mat2 ma = mat2(co, si, -si, co);
    vec2 M = vec2(0);
    vec4 O=fragColor;

 O-=O;
	for(float i=0.;i<500.;i++)    
    	O+=vec4((1.11-cos((vec3(3,7,1)+i*0.1)))
        	*exp(-9.*length(cross((abs(fract(fract(
                10.*sin((vec3(10,5,9)+i*1.)))+iTime*0.002)*1.0-1.)*1.3-1.)*20.,
                   vec3(gl_FragCoord.xy/iResolution.y-.5,1)))),1)+1e-4;

    float t4 = iTime*Velocity*0.; 
    vec3 col = vec3(0);  
    for(float i=0.; i<1.; i+=1./NUM_LAYERS){
        float depth = fract(i+t4);
        float scale = mix(CanvasView, .5, depth);
        float fade = depth*smoothstep(1.,.9,depth);
        col += StarLayer(uv*scale+i*453.2-iTime*.00)*fade;}   
    vec4 o=fragColor;
    vec2 F = fragCoord;
   vec2 R = iResolution.xy; 
    o-=o;
    for(float d,t = -iTime*.002, i = 0. ; i > -1.; i -= .06 )          	
    {   d = fract( i -3.*t );                                          	
        vec4 c = vec4( ( F - R *.5 ) / R.y *d ,i,0 ) * 28.;            	
        for (int j=0 ; j++ <27; )                                      	
            c.xzyw = abs( c / dot(c,c)                                 	
                    -vec4( 7.-.2*sin(t) , 6.3 , .7 , 1.-cos(t3/.8))/7.);	
       o -= c * c.yzww  * d--*d  / vec4(3,5,1,1);                     
    }


   	float t = iTime * SPEED;
     float time = iTime * .2 + 23.0;
    vec2 uv3 = fragCoord.xy / iResolution.xy;

    vec2 p = mod(uv3 * TAU, TAU) - 250.0  ;
    vec2 i = vec2(p);
    float c3 = 1.0;
    float inten =  0.005;

    for (int n = 0; n < MAX_ITER; n++) {
        float t = time * (1.0 - (3.5 / float(n + 1)));
        i = p + vec2(cos(t - i.x) + sin(t + i.y), sin(t - i.y) + cos(t + i.x));
        c3 += 1.0 / length(vec2(p.x / (sin(i.x + t) / inten + spectrum), p.y / (cos(i.y + t) / inten)));
    }

    c3 /= float(MAX_ITER);
    c3 = 1.17-pow(c3, 1.4);
    vec3 colour = vec3(pow(abs(c3), 8.0));
    //colour = clamp(colour + vec3(spectrum.x, spectrum.y, spectrum.x), 0.0, 1.0);
    vec2 fishuv;
    float fishyness = (0.1 + 0.1) * INTENSITY;
    fishuv.x = -(uv.y*uv.y * cos(t))* fishyness * uv.x;
    fishuv.y = -(uv.x*uv.x * sin(t))* fishyness * uv.y;
    fishuv*=ma;
    uv+= fishuv;

	vec3 finalColor=vec3(0);
	float c=smoothstep(0.1,0.0,clamp(uv.x*.01*cos(iTime)+.99,0.,.99));
	c+=snow(uv,3.)*.8;
	c+=snow(uv,5.)*.7;
	c+=snow(uv,7.)*.6;

	c+=snow(uv,9.)*.5;

	c+=snow(uv,11.)*.4;

	c+=snow(uv,13.)*.3;

	c+=snow(uv,15.)*.2+o.y*0.01;

	c+=snow(uv,17.)*.1+o.x*0.01;

	finalColor=(vec3(c*1.0*cos(iTime),c*0.8,c*01.9));
	fragColor = vec4(finalColor+col*0.01,1)*81.0;
      uv *= 2.0 * ( cos(iTime * 2.0) -2.5); // scale
    float anim = sin(iTime * 12.0) * 0.1 + 1.0;  // anim between 0.9 - 1.1 
    fragColor+= vec4(happy_star(uv, anim) * vec3(0.35,0.2,1.15)*0.2*colour*10., 1.0);
}
